function detectSocialExpression(msg) {
  if (!msg) return null;
  const normalized = msg.trim().replace(/[!.،؟?✓✗]+$/g, "").replace(/\s+/g, " ").toLowerCase();
  for (const [expr, info] of Object.entries(SOCIAL_EXPRESSIONS)) {
    if (normalized.includes(expr.toLowerCase())) {
      return { expression: expr, ...info };
    }
  }
  if (/^شكر(ا|اً|ك|كم)/.test(normalized) && normalized.length < 40) {
    return { expression: "\u0634\u0643\u0631\u0627", meaning: "\u0634\u0643\u0631\u0627\u064B", response: "\u0628\u0644\u0627 \u0645\u0632\u064A\u0629 \u2014 \u064A\u0633\u0639\u062F\u0646\u064A \u0643\u0646\u062A \u0645\u0641\u064A\u062F \u{1F91D}", category: "thanks" };
  }
  if (/^(سلام|السلام عليكم|مرحبا|أهلا|هلا)\b/.test(normalized) && normalized.length < 30) {
    return { expression: normalized, meaning: "\u062A\u062D\u064A\u0629", response: "\u0648\u0639\u0644\u064A\u0643\u0645 \u0627\u0644\u0633\u0644\u0627\u0645 \u0648\u0631\u062D\u0645\u0629 \u0627\u0644\u0644\u0647 \u2014 \u0643\u064A\u062F\u0627\u064A\u0631\u061F \u0648\u0627\u0634 \u0646\u0642\u062F\u0631 \u0646\u0639\u0627\u0648\u0646\u0643\u061F \u{1F60A}", category: "greeting" };
  }
  if (/^لاباس/.test(normalized) && normalized.length < 25) {
    return { expression: "\u0644\u0627\u0628\u0627\u0633", meaning: "\u0628\u062E\u064A\u0631", response: "\u0627\u0644\u062D\u0645\u062F \u0644\u0644\u0647 \u{1F90D} \u2014 \u0643\u064A\u0641\u0627\u0634 \u0646\u0639\u0627\u0648\u0646\u0643\u061F", category: "casual_shift", isTopicShift: true };
  }
  if (/^(بالمناسبة|على فكرة|بالعلاقة|حاجة أخرى|سؤال آخر|غير الموضوع|بدّل الموضوع)/.test(normalized)) {
    return { expression: normalized.split(" ").slice(0, 3).join(" "), meaning: "\u062A\u063A\u064A\u064A\u0631 \u0645\u0648\u0636\u0648\u0639", response: null, category: "casual_shift", isTopicShift: true };
  }
  return null;
}
