var FR_HINTS = /\b(le|la|les|un|une|des|de|du|et|est|pour|avec|dans|que|qui|comment|pourquoi|où|j['']ai|c['']est|n['']est|s['']il|t['']es)\b|[àâçéèêëîïôûùü]/i;
var EN_HINTS = /\b(the|and|for|with|that|this|what|how|why|where|when|please|build|create|fix|generate|website|app|code|api)\b/i;
function detectLanguage(text3 = "") {
  const s2 = String(text3 || "").trim();
  if (!s2) return "ar";
  const arabicChars = (s2.match(/[\u0600-\u06FF]/g) || []).length;
  const totalChars = s2.replace(/\s/g, "").length || 1;
  const arabicRatio = arabicChars / totalChars;
  if (arabicRatio > 0.25) return "ar";
  const fr = FR_HINTS.test(s2);
  const en = EN_HINTS.test(s2);
  if (fr && !en) return "fr";
  if (en && !fr) return "en";
  if (fr && en) {
    return /[àâçéèêëîïôûùü]/i.test(s2) ? "fr" : "en";
  }
  return "en";
}
function languageInstruction(lang) {
  switch (lang) {
    case "ar":
      return "\u064A\u062C\u0628 \u0623\u0646 \u062A\u062C\u064A\u0628 \u0628\u0627\u0644\u0644\u063A\u0629 \u0627\u0644\u0639\u0631\u0628\u064A\u0629 \u0627\u0644\u0641\u0635\u062D\u0649 \u0628\u0623\u0633\u0644\u0648\u0628 \u0637\u0628\u064A\u0639\u064A \u0648\u0648\u0627\u0636\u062D.";
    case "fr":
      return "R\xE9ponds en fran\xE7ais de fa\xE7on claire, naturelle et structur\xE9e.";
    case "en":
    default:
      return "Respond in clear, natural, well-structured English.";
  }
}
function languageLabel(lang) {
  return { ar: "Arabic", fr: "French", en: "English" }[lang] || "English";
}

