function updateProjectFile(id3, file) {
  const meta = INDEX.get(id3);
  if (!meta) return null;
  const dir = path5.join(ROOT, id3);
  const rel = file.path.replace(/^\/project\/?/, "");
  const full = path5.join(dir, rel);
  ensureDir2(path5.dirname(full));
  fs5.writeFileSync(full, file.content, "utf8");
  const idx = meta.files.findIndex((x) => x.path === file.path);
  const entry = { path: file.path, lang: file.lang || "txt", bytes: Buffer.byteLength(file.content, "utf8") };
  if (idx === -1) meta.files.push(entry);
  else meta.files[idx] = entry;
  meta.fileCount = meta.files.length;
  meta.totalBytes = meta.files.reduce((a, f2) => a + f2.bytes, 0);
  meta.updatedAt = Date.now();
  fs5.writeFileSync(path5.join(dir, "_meta.json"), JSON.stringify(meta, null, 2), "utf8");
  INDEX.set(id3, meta);
  return meta;
}
function listProjects(limit = 25) {
  return Array.from(INDEX.values()).sort((a, b) => b.updatedAt - a.updatedAt).slice(0, limit);
}
function deleteProject(id3) {
  const dir = path5.join(ROOT, id3);
  try {
    fs5.rmSync(dir, { recursive: true, force: true });
  } catch {
  }
  return INDEX.delete(id3);
}
function projectStats() {
  const all = Array.from(INDEX.values());
  return {
    total: all.length,
    totalFiles: all.reduce((a, m2) => a + m2.fileCount, 0),
    totalBytes: all.reduce((a, m2) => a + m2.totalBytes, 0),
    storageRoot: ROOT,
    persistent: !isVercel
  };
}
function ensureDir2(dir) {
  try {
    fs5.mkdirSync(dir, { recursive: true });
  } catch {
  }
}

