async function uploadBase64ToPublicUrl(b64, mime = "image/jpeg") {
  const ext = mime.split("/")[1]?.split("+")[0] || "jpg";
  const buf = Buffer.from(b64, "base64");
  try {
    const blob = new Blob([buf], { type: mime });
    const fd = new FormData();
    fd.append("file", blob, `img.${ext}`);
    const r2 = await fetch("https://tmpfiles.org/api/v1/upload", {
      method: "POST",
      body: fd,
      signal: AbortSignal.timeout(12e3)
    });
    if (r2.ok) {
      const d2 = await r2.json();
      const u = d2?.data?.url;
      if (u) return u.replace("tmpfiles.org/", "tmpfiles.org/dl/");
    }
  } catch (e2) {
    console.warn("[img-upload] tmpfiles:", e2.message);
  }
  try {
    const blob = new Blob([buf], { type: mime });
    const fd = new FormData();
    fd.append("file", blob, `img.${ext}`);
    const r2 = await fetch("https://0x0.st", {
      method: "POST",
      body: fd,
      signal: AbortSignal.timeout(12e3)
    });
    if (r2.ok) {
      const url2 = (await r2.text()).trim();
      if (url2.startsWith("http")) return url2;
    }
  } catch (e2) {
    console.warn("[img-upload] 0x0.st:", e2.message);
  }
  return null;
}
