function classifyIntent4(prompt) {
  const text3 = String(prompt || "").toLowerCase();
  if (!text3) return { intent: "code", confidence: 0, scores: { code: 0, image: 0, chart: 0, map: 0 } };
  const hasImg2VideoSignal = VIDEO_GENERATION_SIGNALS.some((s2) => text3.includes(s2.toLowerCase())) && (text3.includes("\u0635\u0648\u0631\u0629") || text3.includes("image") || text3.includes("photo") || text3.includes("img")) && (text3.includes("\u0641\u064A\u062F\u064A\u0648") || text3.includes("video") || text3.includes("animate"));
  if (hasImg2VideoSignal) {
    return { intent: "img2video", confidence: 0.92, scores: { code: 0, image: 0, chart: 0, map: 0, video: 3, img2video: 4 }, source: "img2video-signal" };
  }
  const hasVideoGenSignal = VIDEO_GENERATION_SIGNALS.some((s2) => text3.includes(s2.toLowerCase()));
  if (hasVideoGenSignal) {
    return { intent: "video", confidence: 0.92, scores: { code: 0, image: 0, chart: 0, map: 0, video: 4 }, source: "video-signal" };
  }
  const hasImg2ImgSignal = IMG2IMG_SIGNALS.some((s2) => text3.includes(s2.toLowerCase()));
  if (hasImg2ImgSignal) {
    return { intent: "img2img", confidence: 0.9, scores: { code: 0, image: 0, chart: 0, map: 0, img2img: 3 }, source: "img2img-signal" };
  }
  const hasImageSearchSignal = IMAGE_SEARCH_SIGNALS.some((s2) => text3.includes(s2.toLowerCase()));
  const hasImageGenSignal = IMAGE_GENERATION_SIGNALS.some((s2) => text3.includes(s2.toLowerCase()));
  if (hasImageSearchSignal && !hasImageGenSignal) {
    return { intent: "image-search", confidence: 0.95, scores: { code: 0, "image-search": 3, image: 0, chart: 0, map: 0 }, source: "image-search-signal" };
  }
  if (MAP_WEBSITE_SIGNALS.some((s2) => text3.includes(s2.toLowerCase()))) {
    return { intent: "map", confidence: 0.9, scores: { code: 0, image: 0, chart: 0, map: 3 }, source: "map-website-signal" };
  }
  const scores = { code: 0, image: 0, chart: 0, map: 0 };
  for (const lang of Object.keys(KEYWORDS)) {
    for (const intent of Object.keys(KEYWORDS[lang])) {
      for (const kw of KEYWORDS[lang][intent]) {
        if (text3.includes(kw.toLowerCase())) scores[intent] += kw.length > 5 ? 2 : 1;
      }
    }
  }
  if (/\b(generate|draw|render|imagine)\s+(a|an|une|un|the)?\s*(image|photo|picture|logo|poster|صورة)/i.test(text3)) scores.image += 3;
  if (/\b(chart|graph|plot|bar|pie|line|dashboard|statistics|مخطط|graphique|diagramme)\b/i.test(text3)) scores.chart += 2;
  if (/\b(website|app|api|server|component|module|script|backend|frontend|موقع|تطبيق|مشروع|projet|application|site)\b/i.test(text3)) scores.code += 2;
  if (/\b(map|maps|carte|خريطة|leaflet|openstreetmap|geo|mapping)\b/i.test(text3)) scores.map += 2;
  if (scores.map > 0 && scores.code > 0) {
    const hasWebKeyword = /\b(website|site|موقع ويب|landing page|صفحة ويب)\b/i.test(text3);
    const hasMapWebsite = /\b(map website|موقع خريطة|site avec carte)\b/i.test(text3);
    if (hasMapWebsite) scores.map += 3;
    else if (hasWebKeyword && !hasMapWebsite) scores.code += 2;
  }
  const total = scores.code + scores.image + scores.chart + scores.map;
  const winner = pickWinner(scores);
  const confidence = total === 0 ? 0 : scores[winner] / total;
  return { intent: winner, confidence: round(confidence), scores };
}
async function classifyWithLLM({ aiGenerate, prompt }) {
  const sys = `You are a single-word intent classifier for an AI agent. Read the user request and reply with ONLY ONE of these tokens, lowercase, no punctuation:
- code   (the user wants source code, a website, app, API, script, project)
- image  (the user wants an image, picture, logo, poster, illustration)
- chart  (the user wants a chart, graph, dashboard, data visualization)
- map    (the user wants an interactive map, map website, or location-based web app using Leaflet/OpenStreetMap)

IMPORTANT: If the user says "\u0645\u0648\u0642\u0639 \u062E\u0631\u064A\u0637\u0629" or "map website" or "site with map", reply with "map".
If the user says "\u0645\u0648\u0642\u0639" or "website" without map context, reply with "code".

Reply with EXACTLY one word from {code, image, chart, map}.`;
  try {
    const raw = await aiGenerate({
      messages: [
        { role: "system", content: sys },
        { role: "user", content: prompt }
      ],
      query: prompt,
      max_tokens: 4
    });
    const text3 = (typeof raw === "string" ? raw : raw?.content || "").toLowerCase();
    const m2 = text3.match(/\b(code|image|chart|map)\b/);
    return m2 ? m2[1] : null;
  } catch {
    return null;
  }
}
async function dispatch({ aiGenerate, prompt }) {
  const cheap = classifyIntent4(prompt);
  if (cheap.confidence >= 0.45 || !aiGenerate) return { ...cheap, source: cheap.source || "keywords" };
  const llm = await classifyWithLLM({ aiGenerate, prompt });
  if (llm) return { intent: llm, confidence: 0.7, scores: cheap.scores, source: "llm" };
  return { ...cheap, source: "keywords-default" };
}
function pickWinner(scores) {
  const entries = Object.entries(scores).sort((a, b) => b[1] - a[1]);
  if (entries[0][1] === entries[1][1]) return "code";
  return entries[0][0];
}
function round(n3) {
  return Math.round(n3 * 100) / 100;
}

