async function fixUnusedVariable(owner, repo, errorText, branch, token) {
  const fixes = [];
  const locations = extractErrorLocation(errorText);
  for (const loc of locations) {
    const { file, line } = loc;
    if (!file || !line) continue;
    try {
      const { content, sha } = await readRepoFile(owner, repo, file, branch, token);
      const lines = content.split("\n");
      const targetLine = lines[line - 1] || "";
      const fixed = targetLine.replace(/const\s+\[(\w+),\s*set/g, (m2, name) => `const [_${name}, set`).replace(/const\s+(\w+)\s*=\s*(?!.*set[A-Z])/g, (m2, name) => `const _${name} = `);
      if (fixed !== targetLine) {
        lines[line - 1] = fixed;
        const newContent = lines.join("\n");
        const result = await writeRepoFile(
          owner,
          repo,
          file,
          newContent,
          `fix: suppress unused variable TS6133 in ${file}:${line}`,
          branch,
          token
        );
        fixes.push({ file, line, action: "unused_var_prefixed", commitSha: result.commitSha });
      }
    } catch (err2) {
      fixes.push({ file, line, action: "failed", reason: err2.message });
    }
  }
  return fixes;
}
async function addGitignore(owner, repo, stack = [], branch, token) {
  const nodeIgnore = `node_modules/
dist/
.env
.env.local
.env.*.local
*.log
.DS_Store
Thumb.db
`;
  const pythonIgnore = `__pycache__/
*.pyc
*.pyo
.env
venv/
.venv/
dist/
build/
*.egg-info/
`;
  const isPython = stack.some((s2) => ["Python", "Django", "Flask", "FastAPI"].includes(s2));
  const content = isPython ? pythonIgnore + nodeIgnore : nodeIgnore;
  const result = await writeRepoFile(
    owner,
    repo,
    ".gitignore",
    content,
    "chore: add .gitignore by DZ Agent",
    branch,
    token
  );
  return { file: ".gitignore", action: "created", commitSha: result.commitSha };
}
