    log2("VERIFY", "\u{1F50E} \u0627\u0644\u062A\u062D\u0642\u0642 \u0645\u0646 \u0646\u062A\u0627\u0626\u062C \u0627\u0644\u062A\u0646\u0641\u064A\u0630...");
