async function handleYouTubeInput(urlOrQuery, opts = {}) {
  const { aiGenerate, preloadedMeta, noSuggestions } = opts;
  if (isYtUrl(urlOrQuery)) {
    const videoId = extractVideoId(urlOrQuery);
    if (!videoId) {
      return { flow: "url", message: "\u26A0\uFE0F \u0644\u0645 \u0623\u062A\u0645\u0643\u0646 \u0645\u0646 \u0627\u0633\u062A\u062E\u0631\u0627\u062C \u0645\u0639\u0631\u0651\u0641 \u0627\u0644\u0641\u064A\u062F\u064A\u0648 \u0645\u0646 \u0627\u0644\u0631\u0627\u0628\u0637." };
    }
    console.log(`[YouTube Insight] URL mode \u2014 videoId: ${videoId} preloaded=${!!preloadedMeta?.title}`);
    let video = await scrapeYouTubePage(videoId);
    if (!video) {
      console.log(`[YouTube Insight] Page scrape failed, trying Invidious for ${videoId}`);
      video = await fetchVideoMetaInvidious(videoId);
    }
    if (!video) {
      if (preloadedMeta?.title) {
        console.log(`[YouTube Insight] Using preloaded meta for ${videoId}: "${preloadedMeta.title}"`);
        video = {
          id: videoId,
          title: preloadedMeta.title,
          description: preloadedMeta.description || "",
          author: preloadedMeta.channel || "",
          duration: preloadedMeta.duration || 0,
          views: preloadedMeta.views || 0,
          published: "",
          keywords: [],
          thumbnail: preloadedMeta.thumbnail || `https://i.ytimg.com/vi/${videoId}/hqdefault.jpg`,
          url: `https://www.youtube.com/watch?v=${videoId}`,
          captionTracks: []
        };
      } else {
        video = {
          id: videoId,
          title: "\u0641\u064A\u062F\u064A\u0648 YouTube",
          description: "",
          author: "",
          duration: 0,
          views: 0,
          published: "",
          keywords: [],
          thumbnail: `https://i.ytimg.com/vi/${videoId}/hqdefault.jpg`,
          url: `https://www.youtube.com/watch?v=${videoId}`,
          captionTracks: []
        };
      }
    } else if (preloadedMeta?.description && (!video.description || video.description.length < preloadedMeta.description.length)) {
      video.description = preloadedMeta.description;
    }
    let captionData = null;
    if (video.captionTracks && video.captionTracks.length > 0) {
      captionData = await fetchCaptionsFromTracks(video.captionTracks);
    }
    const captionNote = !captionData ? "\u0644\u0627 \u062A\u062A\u0648\u0641\u0631 \u062A\u0631\u062C\u0645\u0629 \u2014 \u0627\u0644\u062A\u062D\u0644\u064A\u0644 \u0645\u0628\u0646\u064A \u0639\u0644\u0649 \u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0648\u0627\u0644\u0648\u0635\u0641 \u0648\u0627\u0644\u0643\u0644\u0645\u0627\u062A \u0627\u0644\u0645\u0641\u062A\u0627\u062D\u064A\u0629." : null;
    let analysisText = "";
    if (aiGenerate) {
      try {
        const prompt = buildAnalysisPrompt(video, captionData);
        const result = await aiGenerate({
          messages: [{ role: "user", content: prompt }],
          query: video.title,
          max_tokens: 1400
        });
        analysisText = result?.content || "";
      } catch (err2) {
        console.error("[YouTube Insight] AI analysis error:", err2.message);
        analysisText = `### \u{1F3AC} \u0645\u0644\u062E\u0635 \u0627\u0644\u0641\u064A\u062F\u064A\u0648
**${video.title}**${video.author ? ` \u2014 ${video.author}` : ""}

${video.description?.slice(0, 500) || ""}`;
      }
    } else {
      analysisText = `**${video.title}**${video.author ? ` \u2014 ${video.author}` : ""}

${video.description?.slice(0, 500) || ""}`;
    }
    const analysis = {
      summary: analysisText,
      title: video.title,
      channel: video.author,
      duration: fmtDuration(video.duration),
      views: video.views
    };
    const suggestions2 = noSuggestions ? [] : await buildAISuggestions(video, aiGenerate);
    const message = [
      `\u{1F3AC} **${video.title}**`,
      video.author ? `\u{1F4FA} ${video.author}` : null,
      [
        video.duration > 0 ? `\u23F1\uFE0F ${fmtDuration(video.duration)}` : null,
        video.views > 0 ? `\u{1F441}\uFE0F ${Number(video.views).toLocaleString("ar-DZ")} \u0645\u0634\u0627\u0647\u062F\u0629` : null
      ].filter(Boolean).join(" \xB7 ") || null,
      ``,
      analysisText,
      captionNote ? `
> \u2139\uFE0F ${captionNote}` : null
    ].filter((l) => l !== null).join("\n");
    return {
      flow: "url",
      message,
      video: { ...video, captionTracks: void 0 },
      analysis,
      suggestions: suggestions2,
      captionText: captionData?.text || null,
      captionNote
    };
  }
  const searchQuery = urlOrQuery.replace(/(?:ابحث\s+(?:عن|لي|لنا)|جيبلي|عطيني|شرحلي|شوفلي|حبيت\s+نشوف|بالفيديو|بالفيديوهات|فيديو\s+(?:عن|حول|بخصوص)|يوتيوب|يوتيب|على\s+يوتيوب)/gi, "").replace(/^\s*(?:ابحث|جيب|شوف|عطي)\s+/gi, "").replace(/\s+/g, " ").trim() || urlOrQuery;
  console.log(`[YouTube Insight] Search mode \u2014 query: "${searchQuery}"`);
  const results = await searchYouTube(searchQuery, 8);
  if (!results.length) {
    return {
      flow: "search",
      message: `\u{1F50D} \u0644\u0645 \u0623\u062C\u062F \u0646\u062A\u0627\u0626\u062C \u0644\u0640 **"${searchQuery}"** \u0639\u0644\u0649 YouTube. \u062C\u0631\u0628 \u0643\u0644\u0645\u0627\u062A \u0623\u062E\u0631\u0649.`,
      results: [],
      suggestions: [
        `\u0627\u0628\u062D\u062B \u0639\u0646 "${searchQuery} \u0634\u0631\u062D"`,
        `\u0627\u0628\u062D\u062B \u0639\u0646 "${searchQuery} tutorial"`,
        `\u0627\u0628\u062D\u062B \u0639\u0646 "${searchQuery} \u0644\u0644\u0645\u0628\u062A\u062F\u0626\u064A\u0646"`
      ]
    };
  }
  const suggestions = [
    `\u0634\u0631\u062D \u0644\u064A \u0627\u0644\u0641\u064A\u062F\u064A\u0648 \u0627\u0644\u0623\u0648\u0644`,
    `\u062D\u0644\u0651\u0644 \u0627\u0644\u0641\u064A\u062F\u064A\u0648 \u0627\u0644\u062B\u0627\u0646\u064A`,
    `\u0623\u064A \u0641\u064A\u062F\u064A\u0648 \u062A\u0646\u0635\u062D\u0646\u064A \u0628\u0647\u061F`,
    `\u0627\u0628\u062D\u062B \u0639\u0646 "${searchQuery} \u0644\u0644\u0645\u0628\u062A\u062F\u0626\u064A\u0646"`
  ];
  return {
    flow: "search",
    message: `\u{1F50D} \u0648\u062C\u062F\u062A **${results.length} \u0641\u064A\u062F\u064A\u0648\u0647\u0627\u062A** \u0639\u0646 **"${searchQuery}"** \u2014 \u0627\u062E\u062A\u0631 \u0641\u064A\u062F\u064A\u0648 \u0644\u062A\u062D\u0644\u064A\u0644\u0647:`,
    results,
    suggestions
  };
}
