function formatImageSearchResponse({ images, query, originalQuery, translated }) {
  if (!images || images.length === 0) {
    return [
      `\u{1F50D} **\u0644\u0645 \u0623\u062C\u062F \u0635\u0648\u0631\u0627\u064B \u0645\u0637\u0627\u0628\u0642\u0629 \u0644\u0640:** "${originalQuery}"`,
      "",
      "\u0642\u062F \u064A\u0643\u0648\u0646 \u0627\u0644\u0633\u0628\u0628:",
      "- \u0627\u0644\u0637\u0644\u0628 \u062F\u0642\u064A\u0642 \u062C\u062F\u0627\u064B\u060C \u062C\u0631\u0651\u0628 \u0643\u0644\u0645\u0627\u062A \u0623\u0628\u0633\u0637",
      "- \u0627\u0644\u0645\u0639\u0644\u0645 \u0623\u0648 \u0627\u0644\u0645\u0648\u0636\u0648\u0639 \u063A\u064A\u0631 \u0645\u0648\u062C\u0648\u062F \u0641\u064A \u0642\u0648\u0627\u0639\u062F \u0627\u0644\u0635\u0648\u0631 \u0627\u0644\u0645\u062C\u0627\u0646\u064A\u0629",
      "",
      `\u{1F50E} \u064A\u0645\u0643\u0646\u0643 \u0627\u0644\u0628\u062D\u062B \u064A\u062F\u0648\u064A\u0627\u064B \u0639\u0644\u0649 [Wikimedia Commons](https://commons.wikimedia.org/w/index.php?search=${encodeURIComponent(originalQuery)}&ns6=1)`
    ].join("\n");
  }
  const lines = [
    `\u{1F5BC}\uFE0F **\u0646\u062A\u0627\u0626\u062C \u0627\u0644\u0628\u062D\u062B \u0639\u0646:** "${originalQuery}"${translated ? `
> *(\u0628\u062D\u062B \u0628\u0627\u0644\u0625\u0646\u062C\u0644\u064A\u0632\u064A\u0629: ${query})*` : ""}`,
    ""
  ];
  const SOURCE_ICON = {
    "Pinterest": "\u{1F4CC}",
    "Wikimedia Commons": "\u{1F310}",
    "Openverse": "\u{1F513}"
  };
  images.forEach((img, i) => {
    lines.push(`### ${i + 1}. ${img.title}`);
    lines.push(`![${img.title}](${img.url})`);
    const icon = SOURCE_ICON[img.source] || "\u{1F4C1}";
    const parts = [`${icon} ${img.source}`];
    if (img.creator) parts.push(`\u{1F4F7} ${img.creator.slice(0, 60)}`);
    if (img.license && img.license !== "Pinterest") parts.push(`\u2696\uFE0F ${img.license}`);
    lines.push(`*${parts.join(" \xB7 ")}*`);
    lines.push(`[\u{1F517} \u0627\u0644\u0645\u0635\u062F\u0631](${img.sourceUrl})`);
    lines.push("");
  });
  return lines.join("\n");
}

