function findAlgerianClub(query) {
  const clubs = DZ_SPORTS_STATIC_FACTS.algerian_clubs;
  for (const [key2, club] of Object.entries(clubs)) {
    if (query.includes(key2) || query.includes(club.abbr) || club.name_fr && query.toLowerCase().includes(club.name_fr.toLowerCase())) {
      return club;
    }
  }
  return null;
}
