  /(?:قصيدة|قصة|خطبة|شعر|poem|story|essay|speech)/i,
  /(?:برمجة|كود|سكريبت|code|script|function|class)/i,
  /(?:مرحبا|صباح|مساء|كيف حالك|شكراً|hello|hi|thanks)/i
