  if (facts.occupation) parts.push(`\u{1F4BC} **\u0627\u0644\u0645\u0647\u0646\u0629:** ${facts.occupation}`);
  if (facts.startYear) parts.push(`\u{1F4C6} **\u0645\u0646:** ${facts.startYear}`);
