  if (showBadge) {
    const badge = buildTrustBadge(validation2.trustScore ?? 100, validation2.mismatches);
    const sourceSummary = groundingCtx.sources?.length > 0 ? ` \xB7 ${groundingCtx.sources.length} \u0645\u0635\u062F\u0631` : "";
    enriched += `

---
> ${badge}${sourceSummary}`;
  }
  if ((validation2.trustScore ?? 100) < 80 && (validation2.trustScore ?? 100) >= 50 && groundingCtx.confidence) {
    enriched += buildUncertaintyWarning(groundingCtx.confidence, groundingCtx.primarySource);
  }
