function detectDZSportsAmbiguity(msg) {
  if (!msg || msg.length > 80) return null;
  const hasEntity = SPORTS_ENTITY_PRESENT.some((p2) => p2.test(msg));
  if (hasEntity) return null;
  for (const { re, id: id3 } of SPORTS_AMBIGUOUS_PATTERNS) {
    if (re.test(msg.trim())) {
      const cfg = SPORTS_CLARIFICATION_MAP[id3];
      if (cfg) {
        return {
          needsClarification: true,
          caseId: id3,
          question: cfg.question,
          options: cfg.options
        };
      }
    }
  }
  return null;
}
