function detectDZPoliticsAmbiguity(msg) {
  if (!msg || msg.length > 80) return null;
  for (const { re, id: id3 } of POLITICS_AMBIGUOUS_PATTERNS) {
    if (re.test(msg.trim())) {
      const cfg = POLITICS_CLARIFICATION_MAP[id3];
      if (cfg) {
        return {
          needsClarification: true,
          caseId: id3,
          question: cfg.question,
          options: cfg.options
        };
      }
    }
  }
  return null;
}
function detectDZAmbiguity(msg) {
  const sports = detectDZSportsAmbiguity(msg);
  if (sports) return sports;
  const politics = detectDZPoliticsAmbiguity(msg);
  if (politics) return politics;
  return null;
}
function formatDZClarification(question, options2) {
  const lines = [
    `\u{1F914} **${question}**
`,
    ...(options2 || []).map((o2) => `**${o2.n}.** ${o2.emoji || "\u25AA\uFE0F"} ${o2.label}`),
    "",
    "> \u0627\u062E\u062A\u0631 \u0631\u0642\u0645\u0627\u064B \u0623\u0648 \u0627\u0643\u062A\u0628 \u0645\u0627 \u062A\u0631\u064A\u062F\u0647 \u0628\u0645\u0632\u064A\u062F \u0645\u0646 \u0627\u0644\u062A\u0641\u0627\u0635\u064A\u0644."
  ];
  return lines.join("\n");
}

