var CAPITAL_QUERY_RE = /(?:ما\s+هي\s+|ما\s+|اين\s+|أين\s+)?(?:عاصمة|عاصمت)\s+(.{2,40}?)(?:\?|؟|$)/i;
var CAPITAL_QUERY_FR = /(?:quelle\s+est\s+la\s+)?capitale\s+(?:de\s+(?:la\s+|l['']|du\s+|des\s+)?)?(.{2,35}?)(?:\?|$)/i;
var CAPITAL_QUERY_EN = /(?:what\s+is\s+the\s+)?capital\s+(?:of\s+|city\s+of\s+)?(.{2,35}?)(?:\?|$)/i;
function _matchCapital(query) {
  const q = query.trim();
  let countryName = null;
  const arM = q.match(CAPITAL_QUERY_RE);
  const frM = q.match(CAPITAL_QUERY_FR);
  const enM = q.match(CAPITAL_QUERY_EN);
  if (arM) countryName = arM[1].trim();
  else if (frM) countryName = frM[1].trim();
  else if (enM) countryName = enM[1].trim();
  if (!countryName) return null;
  const cn = countryName.toLowerCase().replace(/[؟?!.،,]/g, "").trim();
  for (const entry of CAPITALS) {
    if (entry.names.some((n3) => cn.includes(n3) || n3.includes(cn))) {
      const isAr = /[\u0600-\u06FF]/.test(query);
      const isFr = /capitale|quelle|est/i.test(query);
      if (isAr) {
        return `\u{1F3D9}\uFE0F \u0639\u0627\u0635\u0645\u0629 **${entry.names[0]}** \u0647\u064A **${entry.capital}** (${entry.capital_fr}).`;
      } else if (isFr) {
        return `\u{1F3D9}\uFE0F La capitale de **${countryName}** est **${entry.capital_fr}**.`;
      } else {
        return `\u{1F3D9}\uFE0F The capital of **${countryName}** is **${entry.capital_fr}** (${entry.capital}).`;
      }
    }
  }
  return null;
}
function lookupStaticFact(query) {
  if (!query || query.length < 3) return null;
  const q = query.trim();
  const capital = _matchCapital(q);
  if (capital) return capital;
  for (const fact of DZ_FACTS) {
    if (fact.patterns.some((p2) => p2.test(q))) return fact.answer;
  }
  for (const fact of MATH_FACTS) {
    if (fact.patterns.some((p2) => p2.test(q))) return fact.answer;
  }
  for (const fact of GENERAL_FACTS) {
    if (fact.patterns.some((p2) => p2.test(q))) return fact.answer;
  }
  return null;
}
function isStaticQuery(query) {
  return !!(CAPITAL_QUERY_RE.test(query) || CAPITAL_QUERY_FR.test(query) || CAPITAL_QUERY_EN.test(query) || [...DZ_FACTS, ...MATH_FACTS, ...GENERAL_FACTS].some((f2) => f2.patterns.some((p2) => p2.test(query))));
}

