var SCORE365_BASE = "https://webws.365scores.com/web";
var SCORE365_HEADERS2 = {
  "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36",
  "Accept": "application/json, text/plain, */*",
  "Accept-Language": "ar,en;q=0.9",
  "Origin": "https://www.365scores.com",
  "Referer": "https://www.365scores.com/"
};
var KOORA_BASE = "https://www.kooora.com";
var KOORA_HEADERS2 = {
  "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
  "Accept": "application/json, */*",
  "Accept-Language": "ar,en;q=0.9",
  "Referer": "https://www.kooora.com/"
};
async function fetch365ScorePlayer2(arabicName, englishName, timeoutMs = 7e3) {
  try {
    const q = encodeURIComponent(englishName);
    const url2 = `${SCORE365_BASE}/search/?query=${q}&langId=1&appTypeId=5`;
    const res = await fetch(url2, { headers: SCORE365_HEADERS2, signal: AbortSignal.timeout(timeoutMs) });
    if (!res.ok) return null;
    const data2 = await res.json();
    const allCandidates = [
      ...data2?.athletes || [],
      ...data2?.competitors || [],
      ...data2?.players || []
    ];
    if (!allCandidates.length) return null;
    const nameParts = englishName.toLowerCase().split(" ").filter((p2) => p2.length > 2);
    const player = (
      // الأولوية: تطابق جميع أجزاء الاسم
      allCandidates.find((p2) => {
        const pn = (p2.name || "").toLowerCase();
        return nameParts.length > 1 ? nameParts.every((part) => pn.includes(part)) : nameParts.some((part) => pn.includes(part));
      }) || // الثانوية: تطابق معظم الأجزاء (أكثر من نصفها)
      allCandidates.find((p2) => {
        const pn = (p2.name || "").toLowerCase();
        const matched = nameParts.filter((part) => pn.includes(part)).length;
        return matched >= Math.ceil(nameParts.length / 2);
      }) || // الأخير فقط إذا كان الاسم قصيراً (كلمة واحدة)
      (nameParts.length === 1 ? allCandidates[0] : null)
    );
    if (!player) return null;
    const clubEn = player.clubName || player.teamName || player.currentTeam?.name || null;
    const leagueEn = player.competitionName || player.league?.name || null;
    const profileUrl = player.nameForURL && player.id ? `https://www.365scores.com/ar/football/player/${player.nameForURL}-${player.id}` : player.id ? `https://www.365scores.com/ar/player/${player.id}` : null;
    return {
      source: "365score",
      clubEn,
      clubAr: clubEn ? EN_CLUB_AR[clubEn.toLowerCase()] || clubEn : null,
      leagueEn,
      leagueAr: leagueEn ? EN_LEAGUE_AR[leagueEn.toLowerCase()] || leagueEn : null,
      position: player.position || null,
      nationality: player.nationality || null,
      playerId: player.id || null,
      profileUrl
    };
  } catch {
    return null;
  }
}
async function fetchKooraPlayer2(arabicName, englishName) {
  try {
    const q = encodeURIComponent(arabicName || englishName);
    const url2 = `${KOORA_BASE}/api/search?q=${q}&type=player`;
    const res = await fetch(url2, { headers: KOORA_HEADERS2, signal: AbortSignal.timeout(5e3) });
    if (!res.ok) return null;
    const data2 = await res.json();
    const player = (data2?.players || data2?.results || [])[0];
    if (!player) return null;
    const clubAr = player.team_name_ar || player.teamAr || null;
    const clubEn = player.team_name || player.teamEn || null;
    return {
      source: "koora",
      clubEn,
      clubAr: clubAr || (clubEn ? EN_CLUB_AR[clubEn.toLowerCase()] || clubEn : null),
      leagueEn: player.league_name || null,
      leagueAr: player.league_name_ar || null,
      position: player.position_ar || player.position || null,
      nationality: player.nationality_ar || player.nationality || null
    };
  } catch {
    return null;
  }
}
