  router3.post("/dz-agent/github/grep", githubLimiter2, async (req2, res) => {
    const token = req2.body.token || process.env.GITHUB_TOKEN || "";
    const { repo, query, path: searchPath = "", branch } = req2.body;
    if (!token || !repo || !query) return res.status(400).json({ error: "token, repo, query required." });
    if (!isValidGithubRepo(repo)) return res.status(400).json({ error: "Invalid repo." });
    try {
      const branchName = branch || "main";
      const branchRes = await ghFetch4(`/repos/${repo}/branches/${encodeURIComponent(branchName)}`, token);
      if (!branchRes.ok) return res.status(404).json({ error: `Branch "${branchName}" not found` });
      const branchData = await branchRes.json();
      const treeSha = branchData.commit?.commit?.tree?.sha;
      if (!treeSha) return res.status(500).json({ error: "Cannot get tree SHA" });
      const treeRes = await ghFetch4(`/repos/${repo}/git/trees/${treeSha}?recursive=1`, token);
      const treeData = await treeRes.json();
      const files = (treeData.tree || []).filter((f2) => f2.type === "blob" && (!searchPath || f2.path.startsWith(searchPath.replace(/\/$/, "")))).slice(0, 50);
      const lq = query.toLowerCase();
      const results = [];
      const batch = files.slice(0, 15);
      await Promise.allSettled(batch.map(async (f2) => {
        try {
          const r2 = await ghFetch4(`/repos/${repo}/contents/${f2.path}${branch ? `?ref=${encodeURIComponent(branch)}` : ""}`, token);
          if (!r2.ok) return;
          const d2 = await r2.json();
          if (!d2.content) return;
          const content = Buffer.from(d2.content, "base64").toString("utf-8");
          const lines = content.split("\n");
          const matches2 = [];
          lines.forEach((line, i) => {
            if (line.toLowerCase().includes(lq)) {
              matches2.push({ line: i + 1, text: line.trim().slice(0, 200) });
            }
          });
          if (matches2.length > 0) results.push({ path: f2.path, matches: matches2.slice(0, 10) });
        } catch {
        }
      }));
      results.sort((a, b) => b.matches.length - a.matches.length);
      res.json({ repo, query, searchPath: searchPath || "/", files_searched: batch.length, results });
    } catch (err2) {
      res.status(500).json({ error: err2.message });
    }
  });
