    step("pages", wasEnabled ? "\u{1F504} \u0625\u0639\u0627\u062F\u0629 \u062A\u0641\u0639\u064A\u0644 GitHub Pages..." : "\u{1F310} \u062A\u0641\u0639\u064A\u0644 GitHub Pages...");
