app.post("/api/dz-agent/github/verify-env", async (req2, res) => {
  const { repo, branch = "main", token } = req2.body;
  const tok = resolveGitHubToken2(token);
  const report3 = { ok: false, checks: {}, errors: [] };
  if (!tok) {
    report3.errors.push("GITHUB_PERSONAL_ACCESS_TOKEN / GITHUB_TOKEN \u063A\u064A\u0631 \u0645\u0636\u0628\u0648\u0637 \u0641\u064A \u0627\u0644\u0623\u0633\u0631\u0627\u0631");
    return res.status(401).json(report3);
  }
  const hdr = ghHeaders5(tok);
  try {
    const userRes = await fetch("https://api.github.com/user", { headers: hdr, signal: AbortSignal.timeout(8e3) });
    if (!userRes.ok) {
      report3.errors.push("Token \u063A\u064A\u0631 \u0635\u0627\u0644\u062D \u0623\u0648 \u0645\u0646\u062A\u0647\u064A \u0627\u0644\u0635\u0644\u0627\u062D\u064A\u0629");
      return res.status(401).json(report3);
    }
    const user = await userRes.json();
    report3.checks.auth = { ok: true, login: user.login, name: user.name, plan: user.plan?.name || "free" };
  } catch (e2) {
    report3.errors.push("\u0641\u0634\u0644 \u0627\u0644\u062A\u062D\u0642\u0642 \u0645\u0646 Token: " + e2.message);
    return res.status(500).json(report3);
  }
  if (repo && isValidGithubRepo2(repo)) {
    try {
      const repoRes = await fetch(`https://api.github.com/repos/${repo}`, { headers: hdr, signal: AbortSignal.timeout(8e3) });
      if (repoRes.ok) {
        const rd = await repoRes.json();
        report3.checks.repo = { ok: true, full_name: rd.full_name, private: rd.private, default_branch: rd.default_branch, has_pages: rd.has_pages };
      } else {
        report3.checks.repo = { ok: false, error: `HTTP ${repoRes.status}` };
      }
    } catch (e2) {
      report3.checks.repo = { ok: false, error: e2.message };
    }
    if (report3.checks.repo?.ok) {
      try {
        const brRes = await fetch(`https://api.github.com/repos/${repo}/git/ref/heads/${encodeURIComponent(branch)}`, { headers: hdr, signal: AbortSignal.timeout(8e3) });
        report3.checks.branch = { ok: brRes.ok, branch, sha: brRes.ok ? (await brRes.json())?.object?.sha : null };
      } catch (e2) {
        report3.checks.branch = { ok: false, error: e2.message };
      }
      try {
        const pgRes = await fetch(`https://api.github.com/repos/${repo}/pages`, { headers: hdr, signal: AbortSignal.timeout(8e3) });
        if (pgRes.ok) {
          const pg = await pgRes.json();
          report3.checks.pages = { ok: true, status: pg.status, url: pg.html_url, source_branch: pg.source?.branch };
        } else {
          report3.checks.pages = { ok: false, status: "not_enabled" };
        }
      } catch {
        report3.checks.pages = { ok: false, status: "unknown" };
      }
    }
  }
  try {
    const scopeRes = await fetch("https://api.github.com/rate_limit", { headers: hdr, signal: AbortSignal.timeout(5e3) });
    const scopes = scopeRes.headers.get("x-oauth-scopes") || "";
    report3.checks.permissions = {
      ok: true,
      scopes: scopes.split(",").map((s2) => s2.trim()).filter(Boolean),
      has_repo: scopes.includes("repo") || scopes.includes("public_repo"),
      has_workflow: scopes.includes("workflow"),
      has_pages: scopes.includes("pages"),
      rate_limit: {
        remaining: parseInt(scopeRes.headers.get("x-ratelimit-remaining") || "0"),
        limit: parseInt(scopeRes.headers.get("x-ratelimit-limit") || "0")
      }
    };
  } catch {
    report3.checks.permissions = { ok: false };
  }
  report3.ok = report3.errors.length === 0;
  console.log(`[GH:verify-env] ${report3.checks.auth?.login || "unknown"} \u2014 ${JSON.stringify(report3.checks)}`);
  return res.json(report3);
});
