app.post("/api/dz-agent/smart-repos/import", async (req2, res) => {
  const { repoName = "", currentRepo = "", token = "", projectContext = "" } = req2.body;
  const repo = getRepoByName(repoName);
  if (!repo) return res.status(404).json({ error: `\u0644\u0645 \u064A\u064F\u0639\u062B\u0631 \u0639\u0644\u0649 \u0645\u0633\u062A\u0648\u062F\u0639: ${repoName}` });
  const files = repo.starterFiles || {};
  const fileList = Object.entries(files).map(([path16, content]) => ({ path: path16, content, lines: content.split("\n").length }));
  if (token && currentRepo && isValidGithubRepo2(currentRepo)) {
    try {
      const pushed = [];
      for (const { path: path16, content } of fileList) {
        const ghPath = `smart-import/${repo.name.toLowerCase()}/${path16}`;
        let sha = null;
        try {
          const r2 = await ghFetch5(`/repos/${currentRepo}/contents/${ghPath}`, token);
          if (r2.ok) {
            const d2 = await r2.json();
            sha = d2.sha;
          }
        } catch (_) {
        }
        const body = { message: `feat: \u0627\u0633\u062A\u064A\u0631\u0627\u062F ${repo.name} \u2014 ${path16}`, content: Buffer.from(content).toString("base64") };
        if (sha) body.sha = sha;
        const pr = await ghFetch5(`/repos/${currentRepo}/contents/${ghPath}`, token, { method: "PUT", body: JSON.stringify(body) });
        if (pr.ok) pushed.push(ghPath);
      }
      return res.status(200).json({
        success: true,
        repo: repo.name,
        pushedFiles: pushed,
        files: fileList,
        install: repo.install,
        message: `\u2705 \u062A\u0645 \u0627\u0633\u062A\u064A\u0631\u0627\u062F **${repo.name}** \u0625\u0644\u0649 \u0645\u0633\u062A\u0648\u062F\u0639 \`${currentRepo}\` \u2014 ${pushed.length} \u0645\u0644\u0641\u0627\u062A \u0641\u064A \u0645\u062C\u0644\u062F \`smart-import/${repo.name.toLowerCase()}/\``
      });
    } catch (err2) {
      console.error(`[SmartImport] GitHub push error:`, err2.message);
    }
  }
  return res.status(200).json({
    success: true,
    repo: repo.name,
    category: repo.category,
    categoryLabel: CATEGORY_LABELS[repo.category] || repo.category,
    files: fileList,
    install: repo.install,
    message: `\u2705 \u0645\u0644\u0641\u0627\u062A **${repo.name}** \u062C\u0627\u0647\u0632\u0629 \u2014 ${fileList.length} \u0645\u0644\u0641\u0627\u062A`
  });
});
app.post("/api/dz-agent/github/create-repo", async (req2, res) => {
  const token = req2.body.token || process.env.GITHUB_TOKEN || "";
  if (!token) return res.status(400).json({ error: "GitHub token required." });
  const { name, description = "", isPrivate = false, autoInit = true } = req2.body;
  if (!name || typeof name !== "string" || !/^[\w\-\.]{1,100}$/.test(name)) {
    return res.status(400).json({ error: "Invalid repository name. Use letters, numbers, hyphens, dots (max 100 chars)." });
  }
  try {
    const r2 = await ghFetch5("/user/repos", token, {
      method: "POST",
      body: JSON.stringify({ name, description, private: !!isPrivate, auto_init: autoInit })
    });
    const data2 = await r2.json();
    if (!r2.ok) return res.status(r2.status).json({ error: data2.message || "Failed to create repository." });
    console.log(`[GitHub] \u2705 Created repo: ${data2.full_name}`);
    return res.status(201).json({
      success: true,
      full_name: data2.full_name,
      html_url: data2.html_url,
      clone_url: data2.clone_url,
      default_branch: data2.default_branch || "main",
      private: data2.private
    });
  } catch (err2) {
    console.error("[GitHub] create-repo error:", err2);
    return res.status(500).json({ error: "Failed to create repository." });
  }
});
app.post("/api/dz-agent/github/delete-branch", async (req2, res) => {
  const token = req2.body.token || process.env.GITHUB_TOKEN || "";
  const { repo, branch } = req2.body;
  if (!token || !repo || !branch) return res.status(400).json({ error: "Token, repo, and branch required." });
  if (!isValidGithubRepo2(repo)) return res.status(400).json({ error: "Invalid repository name." });
  if (branch === "main" || branch === "master") return res.status(400).json({ error: "Cannot delete default branch." });
  try {
    const r2 = await ghFetch5(`/repos/${repo}/git/refs/heads/${encodeURIComponent(branch)}`, token, { method: "DELETE" });
    if (r2.status === 422 || r2.status === 404) {
      const d2 = await r2.json().catch(() => ({}));
      return res.status(r2.status).json({ error: d2.message || `Branch "${branch}" not found.` });
    }
    if (!r2.ok) {
      const d2 = await r2.json().catch(() => ({}));
      return res.status(r2.status).json({ error: d2.message || "Failed to delete branch." });
    }
    console.log(`[GitHub] \u2705 Deleted branch ${branch} from ${repo}`);
    return res.status(200).json({ success: true, message: `\u062A\u0645 \u062D\u0630\u0641 \u0627\u0644\u0641\u0631\u0639 "${branch}" \u0645\u0646 ${repo}` });
  } catch (err2) {
    console.error("[GitHub] delete-branch error:", err2);
    return res.status(500).json({ error: "Failed to delete branch." });
  }
});
app.post("/api/dz-agent/github/files", async (req2, res) => {
  const token = req2.body.token || process.env.GITHUB_TOKEN || "";
  const { repo, path: path16 = "" } = req2.body;
  if (!token || !repo) return res.status(400).json({ error: "Token and repo required." });
  if (!isValidGithubRepo2(repo)) return res.status(400).json({ error: "Invalid repository name." });
  if (path16 && !isValidGithubPath2(path16)) return res.status(400).json({ error: "Invalid path." });
  try {
    const endpoint = `/repos/${repo}/contents/${path16}`;
    const response = await ghFetch5(endpoint, token);
    const data2 = await response.json();
    if (!response.ok) return res.status(response.status).json({ error: data2.message || "Failed to list files" });
    const files = Array.isArray(data2) ? data2.map((f2) => ({
      name: f2.name,
      path: f2.path,
      type: f2.type === "dir" ? "dir" : "file",
      size: f2.size
    })) : [];
    return res.status(200).json({ files });
  } catch (err2) {
    console.error("GitHub files error:", err2);
    return res.status(500).json({ error: "Failed to list files." });
  }
});
app.post("/api/dz-agent/github/file-content", async (req2, res) => {
  const token = req2.body.token || process.env.GITHUB_TOKEN || "";
  const { repo, path: path16 } = req2.body;
  if (!token || !repo || !path16) return res.status(400).json({ error: "Token, repo, and path required." });
  if (!isValidGithubRepo2(repo)) return res.status(400).json({ error: "Invalid repository name." });
  if (!isValidGithubPath2(path16)) return res.status(400).json({ error: "Invalid file path." });
  try {
    const response = await ghFetch5(`/repos/${repo}/contents/${path16}`, token);
    const data2 = await response.json();
    if (!response.ok) return res.status(response.status).json({ error: data2.message || "Failed to read file" });
    if (data2.encoding !== "base64") return res.status(400).json({ error: "Unsupported file encoding." });
    const content = Buffer.from(data2.content, "base64").toString("utf-8");
    return res.status(200).json({ content, sha: data2.sha, name: data2.name });
  } catch (err2) {
    console.error("GitHub file content error:", err2);
    return res.status(500).json({ error: "Failed to read file." });
  }
});
