app.post("/api/tools/img-remove-bg", import_express16.default.json({ limit: "25mb" }), async (req2, res) => {
  const { imageBase64 } = req2.body;
  if (!imageBase64) return res.status(400).json({ error: "imageBase64 \u0645\u0637\u0644\u0648\u0628" });
  const b64 = imageBase64.includes(",") ? imageBase64.split(",")[1] : imageBase64;
  try {
    const sharp = (await import("sharp")).default;
    const imgBytes = Buffer.from(b64, "base64");
    const { data: raw, info } = await sharp(imgBytes).resize({ width: 1024, height: 1024, fit: "inside", withoutEnlargement: true }).removeAlpha().raw().toBuffer({ resolveWithObject: true });
    const W = info.width, H = info.height, C3 = info.channels;
    const N = W * H;
    const isBg = new Uint8Array(N);
    const visited = new Uint8Array(N);
    const queue = new Int32Array(N * 2);
    let qHead = 0, qTail = 0;
    const seed = (idx) => {
      if (!visited[idx]) {
        visited[idx] = 1;
        queue[qTail++] = idx;
      }
    };
    for (let x = 0; x < W; x++) {
      seed(x);
      seed((H - 1) * W + x);
    }
    for (let y2 = 1; y2 < H - 1; y2++) {
      seed(y2 * W);
      seed(y2 * W + W - 1);
    }
    let bR = 0, bG = 0, bB = 0, cnt = qTail;
    for (let i = 0; i < cnt; i++) {
      const p2 = queue[i] * C3;
      bR += raw[p2];
      bG += raw[p2 + 1];
      bB += raw[p2 + 2];
    }
    bR /= cnt;
    bG /= cnt;
    bB /= cnt;
    const THARD = 50, TSOFT = 95;
    while (qHead < qTail) {
      const idx = queue[qHead++];
      const pi = idx * C3;
      const r2 = raw[pi], g = raw[pi + 1], b = raw[pi + 2];
      const dist2 = Math.sqrt((r2 - bR) ** 2 + (g - bG) ** 2 + (b - bB) ** 2);
      if (dist2 > TSOFT) continue;
      isBg[idx] = dist2 < THARD ? 2 : 1;
      const x = idx % W, y2 = idx / W | 0;
      if (x > 0 && !visited[idx - 1]) {
        visited[idx - 1] = 1;
        queue[qTail++] = idx - 1;
      }
      if (x < W - 1 && !visited[idx + 1]) {
        visited[idx + 1] = 1;
        queue[qTail++] = idx + 1;
      }
      if (y2 > 0 && !visited[idx - W]) {
        visited[idx - W] = 1;
        queue[qTail++] = idx - W;
      }
      if (y2 < H - 1 && !visited[idx + W]) {
        visited[idx + W] = 1;
        queue[qTail++] = idx + W;
      }
    }
    const alphaBuf = Buffer.alloc(N);
    for (let i = 0; i < N; i++) {
      alphaBuf[i] = isBg[i] === 2 ? 0 : isBg[i] === 1 ? 80 : 255;
    }
    const alphaImg = sharp(alphaBuf, { raw: { width: W, height: H, channels: 1 } });
    const blurred1 = await alphaImg.clone().blur(2.5).raw().toBuffer();
    const blurred2 = Buffer.alloc(N);
    for (let i = 0; i < N; i++) {
      const v = blurred1[i];
      blurred2[i] = v < 30 ? 0 : v > 200 ? 255 : Math.round((v - 30) / 170 * 255);
    }
    const finalAlpha = await sharp(blurred2, { raw: { width: W, height: H, channels: 1 } }).blur(1.5).raw().toBuffer();
    const rgba = Buffer.alloc(N * 4);
    for (let i = 0; i < N; i++) {
      const si = i * C3, di = i * 4;
      rgba[di] = raw[si];
      rgba[di + 1] = raw[si + 1];
      rgba[di + 2] = raw[si + 2];
      rgba[di + 3] = finalAlpha[i];
    }
    const outBuf = await sharp(rgba, { raw: { width: W, height: H, channels: 4 } }).png().toBuffer();
    console.log("[RemoveBG:flood-fill] ok \u2014", outBuf.length, "bytes");
    return res.json({ imageBase64: `data:image/png;base64,${outBuf.toString("base64")}` });
  } catch (e2) {
    console.warn("[RemoveBG:flood-fill] error:", e2.message.slice(0, 150));
  }
  return res.status(500).json({ error: "\u0641\u0634\u0644 \u0625\u0632\u0627\u0644\u0629 \u0627\u0644\u062E\u0644\u0641\u064A\u0629 \u2014 \u062D\u0627\u0648\u0644 \u0645\u0631\u0629 \u0623\u062E\u0631\u0649 \u0628\u0639\u062F \u0644\u062D\u0638\u0627\u062A" });
});
app.post("/api/tools/img-upscale", import_express16.default.json({ limit: "25mb" }), async (req2, res) => {
  const { imageBase64, scale: scaleStr = "4" } = req2.body;
  if (!imageBase64) return res.status(400).json({ error: "imageBase64 \u0645\u0637\u0644\u0648\u0628" });
  const b64 = imageBase64.includes(",") ? imageBase64.split(",")[1] : imageBase64;
  const inputBuf = Buffer.from(b64, "base64");
  const hfToken = process.env.HF_TOKEN;
  if (hfToken) {
    try {
      const hfRes = await fetch(
        "https://api-inference.huggingface.co/models/caidas/swin2SR-realworld-sr-x4-64-bsrgan-psnr",
        {
          method: "POST",
          headers: { "Authorization": `Bearer ${hfToken}`, "Content-Type": "application/octet-stream" },
          body: inputBuf,
          signal: AbortSignal.timeout(9e4)
        }
      );
      if (hfRes.ok) {
        const outBuf = Buffer.from(await hfRes.arrayBuffer());
        console.log("[Upscale:Swin2SR] ok \u2014", outBuf.length, "bytes");
        return res.json({ imageBase64: `data:image/png;base64,${outBuf.toString("base64")}`, model: "Swin2SR AI" });
      }
      const errTxt = await hfRes.text();
      console.warn("[Upscale:Swin2SR] non-ok:", hfRes.status, errTxt.slice(0, 120), "\u2014 falling back");
    } catch (e2) {
      console.warn("[Upscale:Swin2SR] error:", e2.message, "\u2014 falling back");
    }
  }
  try {
    const sharp = (await import("sharp")).default;
    const meta = await sharp(inputBuf).metadata();
    const scaleN = Math.min(Math.max(parseInt(scaleStr) || 4, 2), 4);
    const MAX = 4096;
    const clampedW = Math.min((meta.width || 512) * scaleN, MAX);
    const clampedH = Math.min((meta.height || 512) * scaleN, MAX);
    const resultBuf = await sharp(inputBuf).resize(clampedW, clampedH, { kernel: "lanczos3", fit: "fill" }).png().toBuffer();
    console.log(`[Upscale:Lanczos] ${meta.width}x${meta.height} \u2192 ${clampedW}x${clampedH}`);
    return res.json({ imageBase64: `data:image/png;base64,${resultBuf.toString("base64")}`, model: "Lanczos3" });
  } catch (e2) {
    console.error("[Upscale]", e2.message);
    return res.status(500).json({ error: "\u0641\u0634\u0644 \u062A\u062D\u0633\u064A\u0646 \u0627\u0644\u0635\u0648\u0631\u0629" });
  }
});
