function _ttsSplitText(text3, max = 190) {
  const parts = [];
  let rem = text3.trim();
  while (rem.length > 0) {
    if (rem.length <= max) {
      parts.push(rem);
      break;
    }
    let cut = rem.lastIndexOf(" ", max);
    if (cut <= 0) cut = max;
    parts.push(rem.slice(0, cut));
    rem = rem.slice(cut).trim();
  }
  return parts;
}
async function _googleTTSFetch(text3, lang) {
  const parts = _ttsSplitText(text3);
  const bufs = [];
  for (const part of parts) {
    const url2 = `https://translate.google.com/translate_tts?ie=UTF-8&q=${encodeURIComponent(part)}&tl=${lang}&client=tw-ob&ttsspeed=1`;
    const resp = await fetch(url2, {
      headers: {
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/124.0 Safari/537.36",
        "Referer": "https://translate.google.com/"
      },
      signal: AbortSignal.timeout(15e3)
    });
    if (!resp.ok) throw new Error(`Google TTS HTTP ${resp.status}`);
    bufs.push(Buffer.from(await resp.arrayBuffer()));
  }
  return Buffer.concat(bufs);
}
async function _kokoroTTSFetch(text3, kokoroVoice, speed = 1) {
  const token = process.env.HF_TOKEN;
  if (!token) throw new Error("HF_TOKEN not configured");
  const resp = await fetch("https://api-inference.huggingface.co/models/hexgrad/Kokoro-82M", {
    method: "POST",
    headers: {
      "Authorization": `Bearer ${token}`,
      "Content-Type": "application/json",
      "Accept": "audio/wav,audio/*,*/*"
    },
    body: JSON.stringify({ inputs: text3, parameters: { voice: kokoroVoice, speed } }),
    signal: AbortSignal.timeout(28e3)
  });
  if (!resp.ok) {
    const msg = await resp.text().catch(() => "");
    throw new Error(`Kokoro HTTP ${resp.status}: ${msg.slice(0, 200)}`);
  }
  return Buffer.from(await resp.arrayBuffer());
}
app.post("/api/tts", async (req2, res) => {
  const { text: text3, voice = "ar-EG-ShakirNeural", speed = 1 } = req2.body || {};
  if (!text3 || typeof text3 !== "string" || text3.trim().length === 0)
    return res.status(400).json({ error: "text is required" });
  if (text3.length > 3e3)
    return res.status(400).json({ error: "text too long (max 3000 chars)" });
  const lang = _TTS_VOICE_LANG[voice] || "ar";
  const kokoroVoice = _KOKORO_VOICE_MAP[voice];
  try {
    let buf;
    if (kokoroVoice) {
      try {
        console.log(`[TTS] Kokoro: voice=${kokoroVoice}`);
        buf = await _kokoroTTSFetch(text3.trim(), kokoroVoice, Number(speed) || 1);
      } catch (kokoroErr) {
        console.warn(`[TTS] Kokoro failed (${kokoroErr.message}), falling back to Google TTS`);
        buf = await _googleTTSFetch(text3.trim(), lang);
      }
    } else {
      buf = await _googleTTSFetch(text3.trim(), lang);
    }
    if (!buf || buf.length === 0) return res.status(500).json({ error: "No audio data received" });
    res.set("Content-Type", "audio/mpeg");
    res.set("Content-Disposition", 'attachment; filename="ai-dz-voice.mp3"');
    res.send(buf);
  } catch (e2) {
    console.error("[TTS] error:", e2.message);
    res.status(500).json({ error: "TTS generation failed", detail: e2.message });
  }
});
